export async function signIn(page, email, password) {
    await page.getByRole("textbox", { name: "Email" }).fill(email);
    await page.getByRole("textbox", { name: "Password" }).fill(password);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    const response = await responsePromise;

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    return response;
}

export async function dismissProjectOwnerReminder(page) {
    await page.getByRole("button", { name: "Remind Later" }).click();
}
